dashboard.definition:
{
	"title": "Agentic Ops",
	"description": "Coordinate telemetry readiness, path health, routing instability, and AI Defense signals.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Agentic Ops",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/agentic-ops.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Agentic Ops\nCoordinate telemetry readiness, path health, routing instability, and AI Defense signals."
			}
		},
		"viz_agentic_ai_defense": {
			"type": "splunk.singlevalueradial",
			"title": "AI Defense Block Rate",
			"dataSources": {
				"primary": "ds_agentic_ai_defense"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('block_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('block_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 20,
						"value": "#8bd45b"
					},
					{
						"from": 20,
						"to": 50,
						"value": "#ff9a4a"
					},
					{
						"from": 50,
						"value": "#ff7169"
					}
				]
			},
			"description": "Single-value block rate for Cisco AI Defense over the dashboard window - share of GenAI prompts and responses denied by policy."
		},
		"viz_agentic_te_feed": {
			"type": "splunk.singlevalueradial",
			"title": "ThousandEyes Feed Age",
			"dataSources": {
				"primary": "ds_agentic_te_feed_health"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#8bd45b"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#ff9a4a"
					},
					{
						"from": 90,
						"value": "#ff7169"
					}
				]
			},
			"description": "Staleness monitor for the ThousandEyes OTel metric stream. Detects feed death within 30 minutes - the typical symptom of an OAuth2 token expiry, endpoint URL change after a TE platform upgrade, or HEC token rotation."
		},
		"viz_agentic_latency": {
			"type": "splunk.singlevalueradial",
			"title": "Avg Latency",
			"dataSources": {
				"primary": "ds_agentic_latency"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('avg_latency_ms') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('avg_latency_ms') | lastPoint() | rangeValue(latencyRange)",
				"unit": "ms"
			},
			"context": {
				"latencyRange": [
					{
						"to": 100,
						"value": "#8bd45b"
					},
					{
						"from": 100,
						"to": 200,
						"value": "#ff9a4a"
					},
					{
						"from": 200,
						"value": "#ff7169"
					}
				]
			},
			"description": "Average round-trip network latency in milliseconds across all Cisco ThousandEyes network tests, with max and 95th-percentile values as a composite network performance KPI for the Agentic Ops pillar."
		},
		"viz_agentic_loss": {
			"type": "splunk.singlevalueradial",
			"title": "Avg Packet Loss",
			"dataSources": {
				"primary": "ds_agentic_loss"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('avg_loss_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('avg_loss_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 1,
						"value": "#8bd45b"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#ff9a4a"
					},
					{
						"from": 5,
						"value": "#ff7169"
					}
				]
			},
			"description": "Average network packet loss percentage across all Cisco ThousandEyes network tests, with maximum loss for outlier context, as the primary network path quality KPI for Agentic Ops."
		},
		"viz_agentic_loss_trend": {
			"type": "splunk.area",
			"title": "Network Loss Trend",
			"dataSources": {
				"primary": "ds_agentic_loss_trend"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#ff7169",
					"#ff9a4a"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Hourly trend of average and maximum network packet loss from Cisco ThousandEyes, enabling detection of transient vs sustained path quality degradation over time."
		},
		"viz_agentic_bgp_changes": {
			"type": "splunk.area",
			"title": "BGP Path Changes",
			"dataSources": {
				"primary": "ds_agentic_bgp_changes"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#7c3aed",
					"#53bfff",
					"#ff9a4a"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Hourly trend of BGP path changes detected by Cisco ThousandEyes per monitored test, surfacing internet routing instability that can degrade application reachability and performance before users report issues."
		},
		"viz_agentic_test_health": {
			"type": "splunk.column",
			"title": "Healthy vs Degraded Tests",
			"dataSources": {
				"primary": "ds_agentic_test_health"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8bd45b",
					"#ff7169"
				]
			},
			"description": "Summary of Cisco ThousandEyes test health — total tests monitored, healthy tests, and degraded tests — derived from network loss and HTTP availability metrics to provide the Agentic Ops visibility KPI."
		},
		"viz_agentic_http_availability": {
			"type": "splunk.bar",
			"title": "HTTP Availability by Test",
			"dataSources": {
				"primary": "ds_agentic_http_availability"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8bd45b",
					"#ff9a4a"
				]
			},
			"description": "Per-test HTTP server availability from Cisco ThousandEyes, showing average and minimum availability percentages with health status for each monitored application or service endpoint."
		},
		"viz_agentic_web_errors": {
			"type": "splunk.singlevalue",
			"title": "Web Transaction Errors",
			"dataSources": {
				"primary": "ds_agentic_web_errors"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('total_errors') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#ff7169"
			},
			"description": "Total count of web transaction errors detected by Cisco ThousandEyes across all monitored web transaction tests, indicating failed steps or HTTP errors encountered during synthetic transaction execution."
		},
		"viz_agentic_feed_matrix": {
			"type": "splunk.table",
			"title": "Telemetry Feed Health Matrix",
			"dataSources": {
				"primary": "ds_agentic_feed_matrix"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 25,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Single-pane consolidated health matrix for every critical Cisco data feed - ThousandEyes, FTD, FMC eStreamer, Catalyst Center, SD-WAN, ISE, Cisco Spaces, IOS syslog, Duo, Meraki, Zeek, and ACI/ND."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Security and network operations  •  **Sources:** AI Defense, ThousandEyes, routing, and feed-health telemetry  •  **Reading guide:** Confirm feed health first, then investigate path quality, routing, and enforcement exceptions.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Operational posture\nConfirm feed health first, then investigate path quality, routing, and enforcement exceptions."
			}
		}
	},
	"dataSources": {
		"ds_agentic_ai_defense": {
			"name": "Security - GenAI Protection - Cisco AI Defense Block Rate",
			"options": {
				"ref": "security_ai_defense_block_rate_kpi",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_te_feed_health": {
			"name": "Feed Monitor - ThousandEyes - Stream Staleness - Signal Rail KPI",
			"options": {
				"ref": "feed_monitor_thousandeyes_stream_staleness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_latency": {
			"name": "Secure Networking chain - ThousandEyes average latency",
			"options": {
				"ref": "secure_networking_thousandeyes_avg_latency",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_loss": {
			"name": "Secure Networking chain - ThousandEyes packet loss",
			"options": {
				"ref": "secure_networking_thousandeyes_avg_loss_pct",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_loss_trend": {
			"name": "Secure Networking chain - ThousandEyes loss trend",
			"options": {
				"ref": "secure_networking_thousandeyes_network_loss_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_bgp_changes": {
			"name": "Secure Networking chain - ThousandEyes BGP path changes",
			"options": {
				"ref": "secure_networking_thousandeyes_bgp_path_changes_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_test_health": {
			"name": "Secure Networking chain - ThousandEyes test health",
			"options": {
				"ref": "secure_networking_thousandeyes_test_success_vs_failed",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_http_availability": {
			"name": "Secure Networking chain - ThousandEyes HTTP availability",
			"options": {
				"ref": "secure_networking_thousandeyes_http_availability_by_test",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_web_errors": {
			"name": "Secure Networking chain - ThousandEyes web errors",
			"options": {
				"ref": "secure_networking_thousandeyes_web_transaction_errors",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_agentic_feed_matrix": {
			"name": "Feed Monitor - ALL Feeds - Consolidated Health Matrix",
			"options": {
				"ref": "feed_monitor_all_feeds_health_matrix",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1370,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_ai_defense",
						"position": {
							"x": 20,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_te_feed",
						"position": {
							"x": 375,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_latency",
						"position": {
							"x": 730,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_loss",
						"position": {
							"x": 1085,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_loss_trend",
						"position": {
							"x": 20,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_bgp_changes",
						"position": {
							"x": 730,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_test_health",
						"position": {
							"x": 20,
							"y": 754,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_http_availability",
						"position": {
							"x": 730,
							"y": 754,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_web_errors",
						"position": {
							"x": 20,
							"y": 1050,
							"w": 690,
							"h": 190
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_feed_matrix",
						"position": {
							"x": 730,
							"y": 1050,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
